// Compares data/redemption-data.json with the live Supabase database and fails when they differ.
//
//   CALCULATOR_DATABASE_URL=postgres://... node scripts/check-data-drift.mjs
//
// calculator-data.json and recommender-data.json are regenerated by scripts/refresh-calculator-data.mjs.
// redemption-data.json (award charts, transfer rules, redemption values, places) is assembled by hand, so
// nothing else notices when the database moves on. This check recomputes the totals that file is built from
// (scripts/redemption-check.sql) and reports every one that no longer matches.
//
// For a dry run without a database: node scripts/check-data-drift.mjs --db-json path/to/redemption_check.json
import { readFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const readJson = async f => JSON.parse(await readFile(path.join(root, f), 'utf8'));

const dbJsonFlag = process.argv.indexOf('--db-json');

// Totals from the shipped files, in the same shape redemption-check.sql returns.
const fromFiles = async () => {
  const [calc, rec, red] = await Promise.all([readJson('data/calculator-data.json'), readJson('data/recommender-data.json'), readJson('data/redemption-data.json')]);
  const ids = [...new Set([...calc.cards.map(c => c.id), ...rec.cards.map(c => c.id)])];

  const charts = {};
  for (const [pid, ch] of Object.entries(red.charts)) charts[pid] = { rows: ch.rows.length, units: ch.rows.reduce((s, r) => s + r[3], 0), asOf: ch.asOf };

  const xfer = { rows: 0, cards: 0, min: 0, multiple: 0, hours: 0, cap: 0 };
  for (const o of Object.values(red.xfer)) {
    xfer.cards++;
    for (const x of Object.values(o)) { xfer.rows++; xfer.min += x[0] || 0; xfer.multiple += x[1] || 0; xfer.hours += x[3] || 0; xfer.cap += x[4] || 0; }
  }

  const modes = { cards: Object.keys(red.modes).length, modes: 0, sum: 0 };
  for (const o of Object.values(red.modes)) for (const v of Object.values(o)) { modes.modes++; modes.sum += v[0]; }
  modes.sum = Number(modes.sum.toFixed(4));
  return { ids, check: { charts, xfer, modes } };
};

const fromDatabase = async ids => {
  if (dbJsonFlag > -1) {
    const dry = JSON.parse(await readFile(path.resolve(process.argv[dbJsonFlag + 1]), 'utf8'));
    return dry.redemption_check ?? dry;
  }
  const url = process.env.CALCULATOR_DATABASE_URL;
  if (!url) { console.error('CALCULATOR_DATABASE_URL is not set.'); process.exit(2); }
  const { default: pg } = await import('pg');
  const client = new pg.Client({ connectionString: url, ssl: { rejectUnauthorized: false } });
  await client.connect();
  try {
    await client.query('begin read only');
    const { rows } = await client.query(await readFile(path.join(root, 'scripts/redemption-check.sql'), 'utf8'), [ids]);
    await client.query('rollback');
    return rows[0].redemption_check;
  } finally {
    await client.end();
  }
};

const flatten = (o, prefix = '') => Object.entries(o).flatMap(([k, v]) => (v && typeof v === 'object' ? flatten(v, `${prefix}${k}.`) : [[`${prefix}${k}`, v]]));

const { ids, check } = await fromFiles();
const db = await fromDatabase(ids);

const f = new Map(flatten(check)), d = new Map(flatten(db));
const keys = [...new Set([...f.keys(), ...d.keys()])].sort();
const diffs = keys.filter(k => String(f.get(k)) !== String(d.get(k)));

if (!diffs.length) {
  console.log(`redemption-data.json matches the database (${keys.length} totals checked).`);
  process.exit(0);
}
console.error(`redemption-data.json is OUT OF DATE: ${diffs.length} of ${keys.length} totals differ from the database.\n`);
console.error('total'.padEnd(26) + 'site file'.padEnd(16) + 'database');
for (const k of diffs) console.error(k.padEnd(26) + String(f.get(k) ?? '-').padEnd(16) + String(d.get(k) ?? '-'));
console.error('\nWhat each total means: charts.* = award chart rows and price sums per programme; xfer.* = transfer minimums,');
console.error('multiples, processing hours and caps; modes.* = bank redemption values (statement credit, vouchers, ...).');
console.error('Regenerate redemption-data.json with scripts/redemption-data.sql, then rerun this check.');
process.exit(1);
